import math
def is_sq(x): r = math.isqrt(x); return r * r == x
def is_cube(x):
    r = round(x ** (1 / 3))
    return any((r + d) ** 3 == x for d in (-1, 0, 1))
print(next(x for x in range(101, 10**6) if is_sq(x) and is_cube(x)))

